INSERT INTO public.meal_templates (user_id, meal_name, meal_type, day_of_week, calories, protein, carbs, fat, fiber, notes) VALUES (3, 'Meal 1 - Eggs, Whey & Carbs (High Protein)', 'Breakfast', 'Usual', 680, 54.0, 46.0, 26.0, 6.0, '3 whole eggs + 3 egg whites + 1 scoop whey in water + 1 tbsp coconut oil + Salad + 150g sweet potato (or 150g potato / 150g cooked rice / 2 rotis) + 50g curd/yogurt. ACV 15m before. Supplements: Calcium citrate + Magnesium + Vitamin D3.');
INSERT INTO public.meal_templates (user_id, meal_name, meal_type, day_of_week, calories, protein, carbs, fat, fiber, notes) VALUES (3, 'Meal 2 - Seasonal Fruit, Whey & Peanuts', 'Lunch', 'Usual', 380, 24.0, 38.0, 16.0, 5.0, '200g+ seasonal fruit + 1/2 scoop whey protein + 30g peanuts. Supplement: 1 multivitamin.');
INSERT INTO public.meal_templates (user_id, meal_name, meal_type, day_of_week, calories, protein, carbs, fat, fiber, notes) VALUES (3, 'Meal 3 / Dinner - Sautéed Paneer & Roti', 'Dinner', 'Usual', 760, 42.0, 34.0, 48.0, 6.0, '200g paneer sautéed in ghee + 1 roti + Salad as desired + 30g dry fruits / nuts. ACV 15m before. Supplement: ZMA with dinner.');
INSERT INTO public.meal_templates (user_id, meal_name, meal_type, day_of_week, calories, protein, carbs, fat, fiber, notes) VALUES (3, 'Before Bed - Gut Recovery & Sleep Protocol', 'Snack', 'Usual', 45, 2.0, 6.0, 2.0, 4.0, '1/2 spoon isabgol (psyllium husk) + 1/2 spoon chia seeds + Ashwagandha in water.');
